-- Expands the SAA question bank to three full exams' worth, spread by the
-- official exam-guide domain weights. Answers stay server-only (no client SELECT policy).

insert into public.questions (
  cert_id, domain, prompt, choices, correct_choice_ids, explanation, difficulty, hint
) values
  ('saa', 'Arquiteturas Seguras', 'Uma plataforma de cursos guarda vídeos em um bucket S3 privado e quer que cada aluno baixe um arquivo por, no máximo, 15 minutos, sem tornar o bucket público. Qual é a solução mais simples?', '[{"id": "a", "text": "Gerar URLs pré-assinadas (presigned URLs) com expiração de 15 minutos"}, {"id": "b", "text": "Liberar leitura pública e trocar o nome dos objetos a cada 15 minutos"}, {"id": "c", "text": "Criar um usuário IAM para cada aluno"}, {"id": "d", "text": "Ativar a hospedagem de site estático no bucket"}]'::jsonb, array['a'], 'URLs pré-assinadas concedem acesso temporário a um objeto específico usando as permissões de quem as gerou, com validade definida, sem expor o bucket.', 'medium', 'Acesso temporário a um objeto privado, sem novas identidades.'),
  ('saa', 'Arquiteturas Seguras', 'Um regulador exige que registros financeiros no S3 não possam ser apagados nem sobrescritos por 7 anos, nem mesmo pelo usuário root. Qual configuração atende?', '[{"id": "a", "text": "S3 Object Lock em modo de conformidade (compliance) com retenção de 7 anos"}, {"id": "b", "text": "Regra de ciclo de vida movendo os objetos para Glacier Deep Archive"}, {"id": "c", "text": "Versionamento com uma bucket policy que nega DeleteObject"}, {"id": "d", "text": "S3 Object Lock em modo de governança com retenção de 7 anos"}]'::jsonb, array['a'], 'No modo compliance, nenhuma identidade, inclusive o root, consegue remover a proteção ou apagar versões antes do fim da retenção. No modo de governança, usuários com permissão especial podem contornar a trava, e uma bucket policy pode ser alterada.', 'hard', 'Nem o root pode contornar: qual modo garante isso?'),
  ('saa', 'Arquiteturas Seguras', 'Uma auditoria exige que o bucket S3 recuse qualquer requisição feita sem HTTPS. Como implementar?', '[{"id": "a", "text": "Ativar o S3 Transfer Acceleration"}, {"id": "b", "text": "Ativar a criptografia padrão SSE-S3 no bucket"}, {"id": "c", "text": "Habilitar o versionamento do bucket"}, {"id": "d", "text": "Bucket policy com Deny para requisições em que aws:SecureTransport é false"}]'::jsonb, array['d'], 'A condição aws:SecureTransport indica se a requisição usou TLS. Um Deny quando ela é false bloqueia acessos por HTTP simples. SSE-S3 trata de criptografia em repouso, não em trânsito.', 'medium', 'A exigência é sobre criptografia em trânsito.'),
  ('saa', 'Arquiteturas Seguras', 'Ao criptografar dados com o AWS KMS, a aplicação gera uma chave de dados, criptografa o arquivo localmente com ela e armazena a chave de dados criptografada junto ao arquivo. Como se chama essa técnica?', '[{"id": "a", "text": "Hashing com sal"}, {"id": "b", "text": "Tokenização"}, {"id": "c", "text": "Criptografia de envelope (envelope encryption)"}, {"id": "d", "text": "Criptografia do lado do servidor com chaves do cliente (SSE-C)"}]'::jsonb, array['c'], 'Na criptografia de envelope, a chave KMS protege apenas a chave de dados. Isso evita enviar grandes volumes ao KMS e permite criptografar localmente com bom desempenho.', 'hard', 'Uma chave dentro de outra chave.'),
  ('saa', 'Arquiteturas Seguras', 'Em uma arquitetura de três camadas, as instâncias de aplicação devem aceitar tráfego na porta 8080 SOMENTE do Application Load Balancer, mesmo que os IPs do ALB mudem. Como configurar?', '[{"id": "a", "text": "Regra de entrada com os IPs atuais do ALB"}, {"id": "b", "text": "Regra de entrada com o CIDR da VPC inteira na porta 8080"}, {"id": "c", "text": "Uma NACL liberando a porta 8080 para 0.0.0.0/0"}, {"id": "d", "text": "Regra de entrada no security group da aplicação que referencia o security group do ALB como origem"}]'::jsonb, array['d'], 'Security groups podem referenciar outros security groups como origem. Assim, qualquer interface associada ao SG do ALB é permitida, independentemente dos IPs.', 'medium', 'Os IPs do ALB mudam; use uma identidade que não muda.'),
  ('saa', 'Arquiteturas Seguras', 'Uma NACL customizada permite entrada na porta 443 vinda da internet, mas os clientes não recebem resposta do servidor web. O security group está correto. Qual é a causa mais provável?', '[{"id": "a", "text": "A NACL precisa de uma regra de entrada para a porta 80"}, {"id": "b", "text": "O security group precisa de uma regra de saída para a porta 443"}, {"id": "c", "text": "Falta uma regra de saída na NACL liberando as portas efêmeras (1024-65535)"}, {"id": "d", "text": "O internet gateway não suporta HTTPS"}]'::jsonb, array['c'], 'NACLs são stateless: o tráfego de resposta precisa ser liberado explicitamente. As respostas saem para as portas efêmeras do cliente, então a regra de saída deve cobri-las.', 'hard', 'Lembre que NACLs não guardam o estado da conexão.'),
  ('saa', 'Arquiteturas Seguras', 'Instâncias em sub-redes privadas precisam enviar mensagens para o Amazon SQS sem passar pela internet ou por um NAT gateway. O que criar?', '[{"id": "a", "text": "Um internet gateway com uma rota para o SQS"}, {"id": "b", "text": "Um VPC endpoint de interface (AWS PrivateLink) para o SQS"}, {"id": "c", "text": "Um VPC endpoint do tipo gateway para o SQS"}, {"id": "d", "text": "Um VPC peering com a conta da AWS"}]'::jsonb, array['b'], 'VPC endpoints de interface criam ENIs privadas na VPC para serviços como SQS, KMS e Secrets Manager. Endpoints do tipo gateway existem apenas para S3 e DynamoDB.', 'medium', 'Somente dois serviços usam endpoints do tipo gateway.'),
  ('saa', 'Arquiteturas Seguras', 'Uma empresa usa um gateway endpoint para o S3 e quer impedir que as instâncias da VPC copiem dados para buckets de outras contas, exfiltrando informações. Qual controle aplicar?', '[{"id": "a", "text": "Uma política no VPC endpoint permitindo acesso somente aos buckets da empresa"}, {"id": "b", "text": "Um security group de saída bloqueando a porta 443"}, {"id": "c", "text": "Desativar a criptografia padrão do bucket"}, {"id": "d", "text": "Uma NACL negando o prefixo do S3"}]'::jsonb, array['a'], 'Políticas de VPC endpoint restringem quais recursos podem ser acessados através do endpoint. Liberar apenas os buckets corporativos impede cópias para buckets externos por esse caminho.', 'hard', 'O próprio endpoint pode ter uma política.'),
  ('saa', 'Arquiteturas Seguras', 'Uma aplicação web atrás de um ALB sofre tentativas de injeção de SQL e cross-site scripting. Qual solução gerenciada mitiga esses ataques com o menor esforço?', '[{"id": "a", "text": "Ativar o AWS Shield Standard"}, {"id": "b", "text": "Adicionar regras de negação em uma NACL para os IPs atacantes"}, {"id": "c", "text": "Associar o AWS WAF ao ALB com os grupos de regras gerenciadas da AWS"}, {"id": "d", "text": "Mover as instâncias para sub-redes privadas"}]'::jsonb, array['c'], 'O WAF inspeciona requisições HTTP na camada 7. Os grupos de regras gerenciadas da AWS já cobrem padrões comuns, como SQLi e XSS, sem escrever regras do zero.', 'medium', 'Os ataques são na camada de aplicação.'),
  ('saa', 'Arquiteturas Seguras', 'Um serviço de streaming só pode exibir conteúdo para usuários no Brasil por questões de licenciamento. O conteúdo é distribuído pelo CloudFront. Qual recurso usar?', '[{"id": "a", "text": "Restrição geográfica do CloudFront"}, {"id": "b", "text": "Uma bucket policy com a condição aws:SourceIp"}, {"id": "c", "text": "Security group permitindo apenas IPs brasileiros"}, {"id": "d", "text": "Política de roteamento por latência do Route 53"}]'::jsonb, array['a'], 'A restrição geográfica do CloudFront permite ou bloqueia países inteiros com base na localização do usuário, na borda, antes de chegar à origem.', 'medium', 'O bloqueio deve acontecer na borda da CDN.'),
  ('saa', 'Arquiteturas Seguras', 'Assinantes premium devem acessar centenas de arquivos de uma área restrita servida pelo CloudFront, sem alterar as URLs de cada arquivo. Qual mecanismo usar?', '[{"id": "a", "text": "Origin Access Control"}, {"id": "b", "text": "Cookies assinados (signed cookies) do CloudFront"}, {"id": "c", "text": "Restrição geográfica"}, {"id": "d", "text": "Uma URL assinada para cada arquivo"}]'::jsonb, array['b'], 'Cookies assinados liberam acesso a múltiplos arquivos sem mudar as URLs. URLs assinadas são melhores para um arquivo específico. OAC protege a origem, mas não identifica assinantes.', 'medium', 'Muitos arquivos e URLs inalteradas.'),
  ('saa', 'Arquiteturas Seguras', 'Uma equipe solicitou um certificado no ACM em sa-east-1 para usar em uma distribuição do CloudFront, mas ele não aparece na lista de certificados da distribuição. Por quê?', '[{"id": "a", "text": "O CloudFront só aceita certificados importados de terceiros"}, {"id": "b", "text": "Certificados do ACM só funcionam com Network Load Balancers"}, {"id": "c", "text": "O certificado precisa estar na mesma Região da origem"}, {"id": "d", "text": "Certificados usados pelo CloudFront precisam ser solicitados ou importados na Região us-east-1"}]'::jsonb, array['d'], 'O CloudFront é um serviço global e só usa certificados do ACM que estejam na Região us-east-1 (Norte da Virgínia).', 'hard', 'Serviços globais têm uma Região de referência.'),
  ('saa', 'Arquiteturas Seguras', 'Um app mobile precisa enviar fotos direto para um bucket S3, cada usuário somente na própria pasta, sem passar por um backend. Qual combinação atende?', '[{"id": "a", "text": "Cognito user pool sem nenhuma política IAM"}, {"id": "b", "text": "Cognito identity pool emitindo credenciais temporárias com política IAM que limita o prefixo ao ID do usuário"}, {"id": "c", "text": "Chaves de acesso de um usuário IAM embutidas no aplicativo"}, {"id": "d", "text": "Bucket público com nomes de arquivo aleatórios"}]'::jsonb, array['b'], 'O identity pool troca o login por credenciais AWS temporárias. Com variáveis de política como o ID da identidade no prefixo, cada usuário só acessa a própria pasta.', 'hard', 'Credenciais temporárias por usuário, limitadas por política.'),
  ('saa', 'Arquiteturas Seguras', 'Uma empresa com 30 contas quer que os funcionários entrem uma vez com o IdP corporativo e recebam conjuntos padronizados de permissões em cada conta. Qual serviço e recurso usar?', '[{"id": "a", "text": "IAM Identity Center com permission sets"}, {"id": "b", "text": "Service Control Policies sem roles"}, {"id": "c", "text": "Cognito user pools com grupos"}, {"id": "d", "text": "Usuários IAM duplicados em cada conta"}]'::jsonb, array['a'], 'O IAM Identity Center centraliza o acesso da força de trabalho a várias contas. Permission sets definem conjuntos de permissões provisionados como roles em cada conta.', 'medium', 'Acesso da força de trabalho a várias contas.'),
  ('saa', 'Arquiteturas Seguras', 'Uma empresa quer que desenvolvedores só acessem instâncias EC2 cuja tag Projeto seja igual à tag Projeto do próprio usuário, sem atualizar políticas a cada novo projeto. Qual abordagem usar?', '[{"id": "a", "text": "Uma política IAM separada listando os ARNs de cada projeto"}, {"id": "b", "text": "Um security group por projeto"}, {"id": "c", "text": "Controle de acesso baseado em atributos (ABAC) comparando aws:PrincipalTag com aws:ResourceTag"}, {"id": "d", "text": "Uma conta AWS por desenvolvedor"}]'::jsonb, array['c'], 'No ABAC, as permissões dependem de atributos (tags) do usuário e do recurso. Uma única política compara as tags e funciona automaticamente para projetos novos.', 'hard', 'A política deve funcionar sem citar projetos específicos.'),
  ('saa', 'Arquiteturas Seguras', 'Uma política deve permitir a exclusão de objetos S3 somente quando o usuário tiver se autenticado com MFA. Qual condição usar?', '[{"id": "a", "text": "aws:SourceVpc igual ao ID da VPC"}, {"id": "b", "text": "aws:MultiFactorAuthPresent igual a true"}, {"id": "c", "text": "s3:x-amz-server-side-encryption igual a aws:kms"}, {"id": "d", "text": "aws:SecureTransport igual a true"}]'::jsonb, array['b'], 'A chave de condição aws:MultiFactorAuthPresent indica se as credenciais da requisição foram obtidas com MFA, permitindo exigir MFA para ações sensíveis.', 'medium', 'O nome da chave descreve o fator extra.'),
  ('saa', 'Arquiteturas Seguras', 'O GuardDuty detecta que uma instância está se comunicando com um servidor de comando e controle. A empresa quer isolá-la automaticamente em segundos. Qual arquitetura implementa isso?', '[{"id": "a", "text": "Regra do EventBridge para o finding do GuardDuty acionando uma Lambda que troca o security group da instância por um de quarentena"}, {"id": "b", "text": "AWS Config enviando um e-mail para a equipe"}, {"id": "c", "text": "Alarme do CloudWatch de CPU que encerra a instância"}, {"id": "d", "text": "Trusted Advisor executando uma verificação diária"}]'::jsonb, array['a'], 'Findings do GuardDuty são publicados no EventBridge. Uma regra pode acionar Lambda ou Systems Manager Automation para remediar automaticamente, como isolar a instância para análise forense.', 'hard', 'Eventos de segurança podem disparar automações.'),
  ('saa', 'Arquiteturas Seguras', 'A empresa quer detectar security groups com a porta 22 aberta para 0.0.0.0/0 e corrigi-los automaticamente. Qual combinação usar?', '[{"id": "a", "text": "Regra do AWS Config com remediação automática via Systems Manager Automation"}, {"id": "b", "text": "CloudTrail com retenção de 90 dias"}, {"id": "c", "text": "Amazon Inspector com relatório semanal"}, {"id": "d", "text": "Amazon Macie com descoberta automática"}]'::jsonb, array['a'], 'O AWS Config avalia continuamente a configuração dos recursos contra regras e pode acionar documentos do Systems Manager Automation para corrigir o que estiver fora de conformidade.', 'medium', 'Avaliar configuração e corrigir automaticamente.'),
  ('saa', 'Arquiteturas Seguras', 'Uma empresa precisa localizar números de CPF e cartões de crédito armazenados por engano em centenas de buckets S3. Qual serviço automatiza essa descoberta?', '[{"id": "a", "text": "Amazon GuardDuty"}, {"id": "b", "text": "AWS Config"}, {"id": "c", "text": "Amazon Macie"}, {"id": "d", "text": "Amazon Inspector"}]'::jsonb, array['c'], 'O Macie usa machine learning e identificadores de dados para descobrir e classificar dados sensíveis no S3, inclusive identificadores personalizados.', 'medium', 'Descoberta de dados sensíveis no S3.'),
  ('saa', 'Arquiteturas Seguras', 'Uma aplicação precisa ler dezenas de parâmetros de configuração, alguns sensíveis, sem necessidade de rotação automática, com o menor custo. Qual serviço usar?', '[{"id": "a", "text": "AWS Systems Manager Parameter Store com parâmetros SecureString"}, {"id": "b", "text": "Amazon DynamoDB com criptografia padrão"}, {"id": "c", "text": "Variáveis de ambiente em texto claro"}, {"id": "d", "text": "AWS Secrets Manager"}]'::jsonb, array['a'], 'O Parameter Store armazena configurações e segredos criptografados com KMS, e a camada padrão não tem custo de armazenamento. O Secrets Manager se justifica quando há rotação automática.', 'medium', 'Sem rotação, o serviço mais caro não é necessário.'),
  ('saa', 'Arquiteturas Seguras', 'Um banco RDS de produção foi criado sem criptografia. Como passar a tê-lo criptografado em repouso?', '[{"id": "a", "text": "Criar uma réplica de leitura criptografada a partir da instância não criptografada"}, {"id": "b", "text": "Ativar a criptografia diretamente nas configurações da instância existente"}, {"id": "c", "text": "Criar um snapshot, copiá-lo com criptografia ativada e restaurar uma nova instância a partir da cópia"}, {"id": "d", "text": "Ativar o SSL nas conexões do banco"}]'::jsonb, array['c'], 'A criptografia de uma instância RDS é definida na criação. O caminho é copiar um snapshot com criptografia e restaurar a partir dele. SSL protege dados em trânsito, não em repouso.', 'hard', 'A criptografia não pode ser ligada na instância existente.'),
  ('saa', 'Arquiteturas Seguras', 'A empresa quer garantir que todo volume EBS criado em uma Região seja criptografado, mesmo que o desenvolvedor esqueça de marcar a opção. O que configurar?', '[{"id": "a", "text": "Criar uma regra de NACL"}, {"id": "b", "text": "Ativar a criptografia EBS por padrão (EBS encryption by default) na Região"}, {"id": "c", "text": "Ativar o AWS Shield Advanced"}, {"id": "d", "text": "Criar uma AMI criptografada e torná-la obrigatória"}]'::jsonb, array['b'], 'Com a criptografia por padrão ativada, todos os novos volumes e cópias de snapshots na Região são criptografados automaticamente com a chave KMS escolhida.', 'medium', 'É uma configuração regional da conta.'),
  ('saa', 'Arquiteturas Seguras', 'Instâncias privadas só podem acessar domínios específicos na internet, como *.github.com, e todo o resto deve ser bloqueado com inspeção stateful. Qual serviço gerenciado usar?', '[{"id": "a", "text": "AWS WAF associado ao NAT gateway"}, {"id": "b", "text": "Security groups com regras de saída por nome de domínio"}, {"id": "c", "text": "AWS Network Firewall com regras de filtragem por domínio"}, {"id": "d", "text": "NACLs com regras por domínio"}]'::jsonb, array['c'], 'O Network Firewall oferece inspeção stateful, filtragem por domínio e IPS para o tráfego da VPC. Security groups e NACLs trabalham com IPs e portas, e o WAF protege aplicações web.', 'hard', 'Security groups e NACLs não entendem nomes de domínio.'),
  ('saa', 'Arquiteturas Seguras', 'Uma empresa quer inserir appliances de firewall de terceiros de forma transparente no caminho do tráfego, com escalabilidade e alta disponibilidade. Qual serviço usar?', '[{"id": "a", "text": "Network Load Balancer com IP estático"}, {"id": "b", "text": "Application Load Balancer"}, {"id": "c", "text": "Gateway Load Balancer"}, {"id": "d", "text": "AWS Global Accelerator"}]'::jsonb, array['c'], 'O Gateway Load Balancer distribui tráfego para appliances virtuais de terceiros (firewalls, IDS/IPS) de forma transparente, usando o protocolo GENEVE, com escala e verificação de saúde.', 'hard', 'Appliances de rede de terceiros no caminho do tráfego.'),
  ('saa', 'Arquiteturas Seguras', 'A segurança quer um único trail do CloudTrail registrando todas as contas do AWS Organizations, inclusive as criadas no futuro, sem configurar conta por conta. O que usar?', '[{"id": "a", "text": "Um organization trail criado na conta de gerenciamento ou de administrador delegado"}, {"id": "b", "text": "Logs de fluxo da VPC em cada conta"}, {"id": "c", "text": "Um alarme do CloudWatch por conta"}, {"id": "d", "text": "Um trail em cada conta criado manualmente"}]'::jsonb, array['a'], 'Um organization trail registra eventos de todas as contas da organização automaticamente, inclusive novas, e as contas-membro não conseguem desativá-lo.', 'medium', 'Um trail que pertence à organização.'),
  ('saa', 'Arquiteturas Seguras', 'Dez equipes acessam o mesmo bucket S3 com permissões diferentes, e a bucket policy ficou enorme e difícil de manter. Qual recurso simplifica isso?', '[{"id": "a", "text": "S3 Access Points, um por equipe, cada um com a própria política"}, {"id": "b", "text": "Um bucket por objeto"}, {"id": "c", "text": "Ativar o S3 Transfer Acceleration"}, {"id": "d", "text": "ACLs de objeto para cada equipe"}]'::jsonb, array['a'], 'Access Points criam endpoints nomeados para o mesmo bucket, cada um com política própria, simplificando o acesso compartilhado em escala.', 'medium', 'Pontos de acesso separados para o mesmo bucket.'),
  ('saa', 'Arquiteturas Seguras', 'Uma conta de parceiro grava objetos em um bucket da sua conta, mas sua equipe não consegue ler esses objetos porque eles pertencem à conta do parceiro. Qual configuração resolve?', '[{"id": "a", "text": "Criar uma regra de ciclo de vida"}, {"id": "b", "text": "Ativar o versionamento do bucket"}, {"id": "c", "text": "Ativar o S3 Transfer Acceleration"}, {"id": "d", "text": "Configurar S3 Object Ownership como ''Bucket owner enforced'', desativando ACLs"}]'::jsonb, array['d'], 'Com ''Bucket owner enforced'', as ACLs são desativadas e o dono do bucket passa a ser dono de todos os objetos, controlando o acesso apenas por políticas.', 'hard', 'O problema é quem é dono do objeto.'),
  ('saa', 'Arquiteturas Seguras', 'Em um app com login pelo Cognito, cada usuário só pode ler e gravar itens de uma tabela DynamoDB cuja partition key seja o seu próprio ID. Qual recurso de política IAM implementa isso?', '[{"id": "a", "text": "Condição dynamodb:LeadingKeys com a variável do ID da identidade do Cognito"}, {"id": "b", "text": "Um security group por usuário"}, {"id": "c", "text": "Criptografia com uma chave KMS por usuário"}, {"id": "d", "text": "Uma tabela DynamoDB para cada usuário"}]'::jsonb, array['a'], 'A condição dynamodb:LeadingKeys restringe o acesso a itens cuja partition key corresponde ao valor informado, como o ID do usuário, oferecendo controle de acesso por item.', 'hard', 'Controle fino no nível da chave de partição.'),
  ('saa', 'Arquiteturas Seguras', 'Uma API do API Gateway deve ser acessível somente de dentro da VPC da empresa, nunca pela internet. Qual configuração usar?', '[{"id": "a", "text": "API otimizada para borda com o CloudFront"}, {"id": "b", "text": "API regional com chave de API obrigatória"}, {"id": "c", "text": "API pública protegida apenas por CORS"}, {"id": "d", "text": "Endpoint de API privado acessado por um VPC endpoint de interface (execute-api), com uma resource policy restringindo a origem"}]'::jsonb, array['d'], 'APIs privadas do API Gateway só são acessíveis por VPC endpoints de interface. A resource policy define quais VPCs ou endpoints podem invocá-las.', 'medium', 'O tipo de endpoint da API define de onde ela é acessível.'),
  ('saa', 'Arquiteturas Seguras', 'A conexão Direct Connect de uma empresa precisa ter o tráfego criptografado por exigência de compliance. Quais são as opções nativas? (Escolha DUAS)', '[{"id": "a", "text": "Usar uma NACL com criptografia"}, {"id": "b", "text": "Habilitar o Shield Advanced na conexão"}, {"id": "c", "text": "Estabelecer uma VPN IPsec sobre a conexão Direct Connect"}, {"id": "d", "text": "Ativar a criptografia padrão do EBS"}, {"id": "e", "text": "Usar MACsec em conexões dedicadas compatíveis"}]'::jsonb, array['c', 'e'], 'O Direct Connect é privado, mas não criptografado por padrão. A criptografia pode vir de uma VPN IPsec sobre o circuito ou de MACsec na camada 2, em conexões dedicadas compatíveis.', 'hard', 'Uma opção atua na camada de rede e a outra na camada de enlace.'),
  ('saa', 'Arquiteturas Seguras', 'Servidores locais de uma empresa precisam chamar APIs da AWS sem chaves de acesso de longa duração. A empresa já tem uma autoridade certificadora interna. Qual serviço usar?', '[{"id": "a", "text": "Chaves de acesso rotacionadas manualmente a cada 90 dias"}, {"id": "b", "text": "AWS Certificate Manager com certificados públicos"}, {"id": "c", "text": "Amazon Cognito user pools"}, {"id": "d", "text": "IAM Roles Anywhere"}]'::jsonb, array['d'], 'O IAM Roles Anywhere permite que cargas fora da AWS obtenham credenciais temporárias de roles IAM usando certificados X.509 de uma CA confiável.', 'medium', 'Credenciais temporárias para cargas fora da AWS.'),
  ('saa', 'Arquiteturas Seguras', 'Quais medidas restringem o acesso a um banco RDS apenas à camada de aplicação? (Escolha DUAS)', '[{"id": "a", "text": "Abrir a porta do banco para o CIDR 0.0.0.0/0 com uma NACL restritiva"}, {"id": "b", "text": "Ativar o acesso público do RDS e restringir por senha forte"}, {"id": "c", "text": "Colocar o banco em sub-redes privadas, sem rota para o internet gateway"}, {"id": "d", "text": "Liberar a porta do banco no security group apenas para o security group da aplicação"}, {"id": "e", "text": "Usar uma réplica de leitura em outra Região"}]'::jsonb, array['c', 'd'], 'Sub-redes privadas impedem exposição direta à internet, e referenciar o security group da aplicação limita quem pode abrir conexões com o banco.', 'medium', 'Pense em isolamento de rede e em origem permitida.'),
  ('saa', 'Arquiteturas Seguras', 'Uma API no API Gateway precisa validar tokens JWT emitidos por um provedor de identidade próprio e aplicar regras de autorização customizadas. Qual recurso usar?', '[{"id": "a", "text": "Um Lambda authorizer"}, {"id": "b", "text": "Uma resource policy com aws:SourceIp"}, {"id": "c", "text": "O AWS WAF com regras gerenciadas"}, {"id": "d", "text": "Uma chave de API com plano de uso"}]'::jsonb, array['a'], 'Lambda authorizers executam lógica própria para validar tokens e devolver uma política de permissão. Chaves de API servem para controle de uso, não para autenticação.', 'medium', 'Lógica de autorização personalizada.'),
  ('saa', 'Arquiteturas Seguras', 'Uma empresa com 50 contas quer que GuardDuty, Security Hub e Inspector sejam gerenciados por uma conta de segurança dedicada, e não pela conta de gerenciamento. Qual prática seguir?', '[{"id": "a", "text": "Designar a conta de segurança como administrador delegado desses serviços no AWS Organizations"}, {"id": "b", "text": "Ativar os serviços manualmente em cada conta e consolidar planilhas"}, {"id": "c", "text": "Compartilhar as credenciais root da conta de gerenciamento"}, {"id": "d", "text": "Criar usuários IAM da conta de segurança em todas as contas"}]'::jsonb, array['a'], 'O administrador delegado permite que uma conta-membro gerencie serviços de segurança para toda a organização, mantendo a conta de gerenciamento com uso mínimo.', 'hard', 'A conta de gerenciamento deve ser usada o mínimo possível.'),
  ('saa', 'Arquiteturas Seguras', 'Quais configurações protegem dados de um bucket S3 em trânsito e em repouso? (Escolha DUAS)', '[{"id": "a", "text": "Criptografia padrão do bucket com SSE-KMS"}, {"id": "b", "text": "Ativar o S3 Transfer Acceleration"}, {"id": "c", "text": "Bucket policy negando requisições sem TLS (aws:SecureTransport false)"}, {"id": "d", "text": "Ativar notificações de eventos do S3"}, {"id": "e", "text": "Usar a classe S3 One Zone-IA"}]'::jsonb, array['a', 'c'], 'Exigir TLS protege os dados em trânsito, e a criptografia padrão com SSE-KMS protege os dados em repouso, com auditoria do uso da chave.', 'medium', 'Uma opção para cada estado dos dados.'),
  ('saa', 'Arquiteturas Seguras', 'Qual é a forma recomendada de dar a uma função Lambda permissão para gravar em uma tabela DynamoDB?', '[{"id": "a", "text": "Usar as credenciais root da conta"}, {"id": "b", "text": "Tornar a tabela pública"}, {"id": "c", "text": "Guardar chaves de acesso de um usuário IAM nas variáveis de ambiente"}, {"id": "d", "text": "Anexar à role de execução da função uma política que permita somente as ações necessárias na tabela"}]'::jsonb, array['d'], 'Toda função Lambda assume uma role de execução. Dar a ela apenas as ações necessárias na tabela segue o menor privilégio e dispensa credenciais fixas.', 'easy', 'Funções Lambda já assumem uma identidade.'),
  ('saa', 'Arquiteturas Seguras', 'Uma aplicação precisa de uma chave KMS cujo uso possa ser concedido a uma role de outra conta AWS. O que deve ser configurado?', '[{"id": "a", "text": "Somente uma política IAM na conta externa"}, {"id": "b", "text": "Um security group permitindo a outra conta"}, {"id": "c", "text": "A key policy da chave gerenciada pelo cliente permitindo a conta externa, além de uma política IAM na conta externa"}, {"id": "d", "text": "Uma chave gerenciada pela AWS (aws/s3) compartilhada"}]'::jsonb, array['c'], 'Para acesso entre contas, a key policy precisa confiar na conta externa e a identidade nessa conta precisa de permissão IAM. Chaves gerenciadas pela AWS não podem ser compartilhadas entre contas.', 'medium', 'Acesso entre contas exige permissão dos dois lados.'),
  ('saa', 'Arquiteturas Seguras', 'A empresa quer centralizar em um painel os findings de segurança de todas as contas e Regiões, priorizados e comparados ao padrão AWS Foundational Security Best Practices. Qual serviço usar?', '[{"id": "a", "text": "AWS Cost Explorer"}, {"id": "b", "text": "AWS Trusted Advisor"}, {"id": "c", "text": "Amazon CloudWatch Logs Insights"}, {"id": "d", "text": "AWS Security Hub com agregação entre Regiões e contas"}]'::jsonb, array['d'], 'O Security Hub agrega findings de serviços AWS e de parceiros em várias contas e Regiões e executa verificações contínuas contra padrões de segurança.', 'medium', 'Painel central de postura de segurança.'),
  ('saa', 'Arquiteturas Resilientes', 'Um Auto Scaling group atrás de um ALB não substitui instâncias cuja aplicação travou, porque elas continuam passando na verificação de status do EC2. O que ajustar?', '[{"id": "a", "text": "Trocar o ALB por um Network Load Balancer"}, {"id": "b", "text": "Aumentar a capacidade desejada do grupo"}, {"id": "c", "text": "Configurar o tipo de verificação de saúde do ASG para incluir as verificações do ELB"}, {"id": "d", "text": "Ativar a proteção contra scale-in"}]'::jsonb, array['c'], 'Por padrão, o ASG usa só as verificações de status do EC2, que não enxergam a aplicação. Incluir as verificações do ELB faz o ASG substituir instâncias que falham no health check do load balancer.', 'medium', 'A instância está viva, mas a aplicação não.'),
  ('saa', 'Arquiteturas Resilientes', 'Um cluster Aurora MySQL tem uma instância de escrita e duas réplicas em AZs diferentes. O que acontece se a instância de escrita falhar?', '[{"id": "a", "text": "O cluster fica indisponível até que um novo snapshot seja restaurado"}, {"id": "b", "text": "As réplicas passam a aceitar escritas simultaneamente"}, {"id": "c", "text": "É preciso recriar o cluster manualmente em outra AZ"}, {"id": "d", "text": "O Aurora promove automaticamente uma das réplicas a instância de escrita, normalmente em menos de um minuto"}]'::jsonb, array['d'], 'As réplicas do Aurora compartilham o mesmo volume distribuído. Em caso de falha, uma réplica é promovida e o endpoint do cluster passa a apontar para ela.', 'medium', 'As réplicas também servem como alvos de failover.'),
  ('saa', 'Arquiteturas Resilientes', 'Uma aplicação global precisa de um banco NoSQL com escrita ativa em várias Regiões e replicação automática, para continuar operando se uma Região inteira cair. Qual solução usar?', '[{"id": "a", "text": "DynamoDB Accelerator (DAX)"}, {"id": "b", "text": "DynamoDB com backups sob demanda copiados para outra Região"}, {"id": "c", "text": "RDS Multi-AZ"}, {"id": "d", "text": "Tabelas globais do DynamoDB (global tables)"}]'::jsonb, array['d'], 'As tabelas globais do DynamoDB replicam automaticamente entre as Regiões escolhidas e permitem leitura e escrita em todas elas (multi-ativo).', 'medium', 'Escrita ativa em várias Regiões.'),
  ('saa', 'Arquiteturas Resilientes', 'Um script com bug apagou milhares de itens de uma tabela DynamoDB às 14h12. Como restaurar a tabela ao estado das 14h11?', '[{"id": "a", "text": "Reverter o DynamoDB Streams"}, {"id": "b", "text": "Usar a recuperação point-in-time (PITR) para restaurar uma nova tabela no momento desejado"}, {"id": "c", "text": "Usar o versionamento do S3 na tabela"}, {"id": "d", "text": "Restaurar a partir de uma réplica de leitura"}]'::jsonb, array['b'], 'Com o PITR ativado, é possível restaurar a tabela em qualquer segundo dentro da janela de retenção configurada. A restauração cria uma nova tabela.', 'medium', 'Recuperação até um instante específico.'),
  ('saa', 'Arquiteturas Resilientes', 'Uma empresa quer cópias automáticas de todos os objetos novos de um bucket S3 em outra Região para DR. Qual pré-requisito é obrigatório?', '[{"id": "a", "text": "O bucket de origem precisa ser público"}, {"id": "b", "text": "Ativar o S3 Transfer Acceleration no destino"}, {"id": "c", "text": "Os dois buckets precisam usar a classe S3 Glacier"}, {"id": "d", "text": "Versionamento ativado nos buckets de origem e de destino"}]'::jsonb, array['d'], 'A replicação entre Regiões (CRR) exige versionamento nos dois buckets e uma role IAM que permita ao S3 replicar os objetos.', 'medium', 'A replicação depende de um recurso que guarda versões.'),
  ('saa', 'Arquiteturas Resilientes', 'Um requisito de compliance exige que 99,99% dos objetos novos estejam replicados na Região de DR em até 15 minutos, com métricas e alertas de atraso. Qual configuração atende?', '[{"id": "a", "text": "Regra de ciclo de vida copiando objetos para outra Região"}, {"id": "b", "text": "Replicação entre Regiões do S3 com S3 Replication Time Control (RTC)"}, {"id": "c", "text": "AWS DataSync agendado a cada hora"}, {"id": "d", "text": "Replicação entre Regiões padrão, sem opções adicionais"}]'::jsonb, array['b'], 'O S3 RTC oferece um SLA de replicação da maioria dos objetos em até 15 minutos, com métricas e notificações de eventos de replicação atrasada.', 'hard', 'Existe uma opção de replicação com tempo garantido.'),
  ('saa', 'Arquiteturas Resilientes', 'Uma empresa quer DR com custo baixo: o banco é replicado continuamente para outra Região, mas os servidores de aplicação só são criados a partir de AMIs durante o desastre. RTO de algumas horas é aceitável. Qual estratégia é essa?', '[{"id": "a", "text": "Backup e restauração"}, {"id": "b", "text": "Multi-site ativo-ativo"}, {"id": "c", "text": "Warm standby"}, {"id": "d", "text": "Pilot light"}]'::jsonb, array['d'], 'No pilot light, apenas o núcleo crítico (como os dados) fica ativo na Região de DR, e o restante é provisionado na hora do desastre. Warm standby mantém uma cópia reduzida de todo o ambiente rodando.', 'hard', 'Só a chama piloto fica acesa.'),
  ('saa', 'Arquiteturas Resilientes', 'Um sistema de pagamentos não pode ficar indisponível nem por poucos minutos, mesmo na perda de uma Região inteira, e o custo é secundário. Qual estratégia de DR escolher?', '[{"id": "a", "text": "Backup e restauração com AWS Backup"}, {"id": "b", "text": "Pilot light"}, {"id": "c", "text": "Warm standby com escala manual"}, {"id": "d", "text": "Multi-site ativo-ativo, servindo tráfego em várias Regiões ao mesmo tempo"}]'::jsonb, array['d'], 'No ativo-ativo, todas as Regiões atendem tráfego continuamente, então a perda de uma Região é absorvida pelas outras com RTO próximo de zero. É a estratégia mais cara.', 'hard', 'RTO próximo de zero tem um preço.'),
  ('saa', 'Arquiteturas Resilientes', 'Um evento de pedido precisa ser entregue a três sistemas independentes (estoque, faturamento e e-mail), cada um processando no próprio ritmo e sem perder mensagens se estiver fora do ar. Qual padrão usar?', '[{"id": "a", "text": "Uma única fila SQS lida pelos três sistemas"}, {"id": "b", "text": "Fan-out com um tópico SNS assinado por três filas SQS"}, {"id": "c", "text": "Três chamadas HTTP síncronas a partir do serviço de pedidos"}, {"id": "d", "text": "Gravar o pedido em um bucket S3 e esperar cada sistema verificar"}]'::jsonb, array['b'], 'O SNS entrega cada mensagem a todas as assinaturas, e cada fila SQS armazena as mensagens até o respectivo consumidor processá-las, isolando falhas.', 'medium', 'Uma mensagem, vários destinos duráveis.'),
  ('saa', 'Arquiteturas Resilientes', 'Vários consumidores diferentes precisam ler o mesmo fluxo de eventos de cliques, na ordem por usuário, e poder reprocessar os eventos das últimas 24 horas. Qual serviço atende melhor?', '[{"id": "a", "text": "Amazon Kinesis Data Streams"}, {"id": "b", "text": "Amazon SQS FIFO com um único consumidor"}, {"id": "c", "text": "Amazon SNS"}, {"id": "d", "text": "Amazon SQS Standard"}]'::jsonb, array['a'], 'O Kinesis Data Streams mantém os registros por um período de retenção, preserva a ordem por chave de partição e permite que vários consumidores leiam e releiam o mesmo fluxo. No SQS, uma mensagem consumida e apagada não pode ser relida.', 'hard', 'Releitura e múltiplos consumidores do mesmo fluxo.'),
  ('saa', 'Arquiteturas Resilientes', 'Uma função Lambda invocada de forma assíncrona às vezes falha, e os eventos que falharam depois de todas as tentativas precisam ser guardados para análise. O que configurar?', '[{"id": "a", "text": "Aumentar o timeout da função para 15 minutos"}, {"id": "b", "text": "Um destino em caso de falha (on-failure destination), como uma fila SQS"}, {"id": "c", "text": "Ativar a concorrência provisionada"}, {"id": "d", "text": "Trocar para invocação síncrona"}]'::jsonb, array['b'], 'Em invocações assíncronas, o Lambda tenta novamente e, após esgotar as tentativas, pode enviar o evento e os detalhes do erro para um destino de falha, como SQS, SNS, EventBridge ou outra função.', 'medium', 'Eventos que esgotam as tentativas precisam de um destino.'),
  ('saa', 'Arquiteturas Resilientes', 'Um fluxo no Step Functions chama uma API externa que falha de vez em quando. Como tornar o fluxo resiliente sem escrever código de retentativa nas funções?', '[{"id": "a", "text": "Executar o fluxo duas vezes em paralelo"}, {"id": "b", "text": "Configurar Retry com backoff exponencial e Catch para tratar o erro nos estados do fluxo"}, {"id": "c", "text": "Aumentar a memória das funções Lambda"}, {"id": "d", "text": "Trocar o Step Functions por uma fila SQS"}]'::jsonb, array['b'], 'O Step Functions tem tratamento de erros declarativo: Retry define tentativas com intervalo e backoff, e Catch direciona falhas para estados de tratamento.', 'medium', 'O próprio serviço de orquestração trata erros.'),
  ('saa', 'Arquiteturas Resilientes', 'Um servidor legado em uma única instância EC2 não pode ser escalado horizontalmente. A empresa quer que ele volte automaticamente se o hardware subjacente falhar, mantendo IP privado e Elastic IP. O que usar?', '[{"id": "a", "text": "Uma réplica em outra Região"}, {"id": "b", "text": "Um snapshot EBS diário"}, {"id": "c", "text": "Um Auto Scaling group com 3 instâncias"}, {"id": "d", "text": "Recuperação automática de instância EC2 (alarme do CloudWatch com ação de recover)"}]'::jsonb, array['d'], 'A recuperação automática migra a instância para outro host quando há falha de hardware, preservando o ID, o IP privado, o Elastic IP e os metadados.', 'medium', 'Recuperar a mesma instância, não criar outra.'),
  ('saa', 'Arquiteturas Resilientes', 'Servidores Windows usam um compartilhamento de arquivos SMB que precisa continuar disponível se uma Zona de Disponibilidade falhar. Qual configuração usar?', '[{"id": "a", "text": "Amazon FSx for Windows File Server em implantação Multi-AZ"}, {"id": "b", "text": "Amazon EBS Multi-Attach"}, {"id": "c", "text": "Amazon FSx for Windows File Server em implantação Single-AZ com backup diário"}, {"id": "d", "text": "Amazon S3 montado como unidade de rede"}]'::jsonb, array['a'], 'No Multi-AZ, o FSx for Windows mantém um servidor standby em outra AZ com replicação síncrona e failover automático.', 'medium', 'Sobreviver à perda de uma AZ exige Multi-AZ.'),
  ('saa', 'Arquiteturas Resilientes', 'Um requisito de auditoria exige backups imutáveis, que nem administradores possam apagar antes do prazo, e uma cópia em outra Região. Qual solução atende?', '[{"id": "a", "text": "Replicação entre Regiões do S3 sem versionamento"}, {"id": "b", "text": "AWS Backup com Vault Lock em modo compliance e regras de cópia entre Regiões"}, {"id": "c", "text": "Snapshots EBS manuais com tags de proteção"}, {"id": "d", "text": "Scripts que copiam snapshots e removem permissões de exclusão"}]'::jsonb, array['b'], 'O Vault Lock do AWS Backup aplica proteção WORM aos pontos de recuperação, e os planos de backup podem copiar automaticamente para cofres em outras Regiões.', 'hard', 'Imutabilidade no cofre de backup.'),
  ('saa', 'Arquiteturas Resilientes', 'Um cluster ElastiCache armazena sessões de usuários e a perda do nó primário derruba todos os logins. Como aumentar a disponibilidade?', '[{"id": "a", "text": "Usar um grupo de replicação com réplicas em outras AZs e failover automático Multi-AZ"}, {"id": "b", "text": "Ativar backups diários do cache"}, {"id": "c", "text": "Mover o cache para a mesma AZ das instâncias"}, {"id": "d", "text": "Aumentar o tamanho do nó primário"}]'::jsonb, array['a'], 'Com Multi-AZ e failover automático, o ElastiCache promove uma réplica em outra AZ quando o primário falha, minimizando a perda de sessões e o tempo de indisponibilidade.', 'medium', 'Réplicas em outras AZs com promoção automática.'),
  ('saa', 'Arquiteturas Resilientes', 'Uma empresa quer DR de um banco RDS MySQL em outra Região com RPO de minutos e baixo custo, aceitando promover o banco manualmente no desastre. Qual solução usar?', '[{"id": "a", "text": "Snapshots semanais copiados para outra Região"}, {"id": "b", "text": "Uma réplica de leitura entre Regiões, promovida a instância independente no desastre"}, {"id": "c", "text": "Uma implantação Multi-AZ na mesma Região"}, {"id": "d", "text": "Uma réplica de leitura na mesma AZ"}]'::jsonb, array['b'], 'Réplicas de leitura entre Regiões recebem atualizações assíncronas com atraso de segundos a minutos e podem ser promovidas a instâncias independentes durante o DR.', 'medium', 'Multi-AZ protege contra falha de AZ, não de Região.'),
  ('saa', 'Arquiteturas Resilientes', 'Uma equipe quer lançar uma nova versão no Elastic Beanstalk com a possibilidade de voltar à anterior instantaneamente. Qual estratégia usar?', '[{"id": "a", "text": "Blue/green: criar um novo ambiente e trocar as URLs (swap environment URLs)"}, {"id": "b", "text": "Implantação all at once no ambiente atual"}, {"id": "c", "text": "Apagar o ambiente atual antes de criar o novo"}, {"id": "d", "text": "Editar o código diretamente nas instâncias"}]'::jsonb, array['a'], 'No blue/green, a nova versão sobe em um ambiente separado. A troca de URLs direciona o tráfego e, se algo der errado, basta trocar de volta.', 'medium', 'Dois ambientes, um interruptor.'),
  ('saa', 'Arquiteturas Resilientes', 'Workers EC2 processam uma fila SQS e o backlog varia muito ao longo do dia. Qual métrica de escala do Auto Scaling mantém o tempo de espera aceitável de forma mais precisa?', '[{"id": "a", "text": "Número total de requisições do ALB"}, {"id": "b", "text": "Escalonamento agendado em horários fixos"}, {"id": "c", "text": "Utilização média de CPU acima de 50%"}, {"id": "d", "text": "Rastreamento de alvo com a métrica de backlog por instância (mensagens visíveis divididas pelo número de instâncias)"}]'::jsonb, array['d'], 'O backlog por instância relaciona o tamanho da fila com a capacidade atual. Com o alvo baseado na latência aceitável e no tempo médio de processamento, o ASG escala na medida certa.', 'hard', 'A escala deve acompanhar o trabalho pendente por worker.'),
  ('saa', 'Arquiteturas Resilientes', 'Um consumidor SQS Standard às vezes recebe a mesma mensagem de pagamento duas vezes, o que causou cobranças duplicadas. Qual é a correção mais robusta mantendo o SQS Standard?', '[{"id": "a", "text": "Reduzir o visibility timeout para 1 segundo"}, {"id": "b", "text": "Usar long polling de 20 segundos"}, {"id": "c", "text": "Tornar o processamento idempotente, registrando o ID do pagamento com escrita condicional no DynamoDB antes de cobrar"}, {"id": "d", "text": "Aumentar o tempo de retenção da fila"}]'::jsonb, array['c'], 'O SQS Standard garante entrega pelo menos uma vez, então duplicatas são possíveis. Consumidores idempotentes, com uma chave de deduplicação gravada de forma condicional, evitam efeitos duplicados.', 'hard', 'Entrega pelo menos uma vez exige processamento idempotente.'),
  ('saa', 'Arquiteturas Resilientes', 'Muitos clientes chamam uma API instável ao mesmo tempo e, quando ela falha, todos tentam de novo no mesmo instante, derrubando-a outra vez. Qual prática evita isso?', '[{"id": "a", "text": "Retentativas imediatas em loop até dar certo"}, {"id": "b", "text": "Desativar as retentativas e descartar as requisições"}, {"id": "c", "text": "Aumentar o timeout dos clientes para 10 minutos"}, {"id": "d", "text": "Retentativas com backoff exponencial e jitter (aleatoriedade)"}]'::jsonb, array['d'], 'O backoff exponencial aumenta o intervalo entre tentativas, e o jitter espalha os clientes no tempo, evitando ondas sincronizadas de requisições.', 'medium', 'Espalhe as novas tentativas no tempo.'),
  ('saa', 'Arquiteturas Resilientes', 'Um cluster Cassandra autogerenciado em EC2 precisa que réplicas de dados fiquem em racks físicos diferentes, com dezenas de instâncias por grupo. Qual placement group usar?', '[{"id": "a", "text": "Nenhum, pois o Auto Scaling já distribui por rack"}, {"id": "b", "text": "Spread placement group"}, {"id": "c", "text": "Cluster placement group"}, {"id": "d", "text": "Partition placement group"}]'::jsonb, array['d'], 'O partition placement group divide as instâncias em partições que não compartilham racks, ideal para sistemas distribuídos e com reconhecimento de topologia, como Cassandra, HDFS e Kafka. O spread é limitado a 7 instâncias por AZ.', 'hard', 'Muitas instâncias, separadas em grupos de racks.'),
  ('saa', 'Arquiteturas Resilientes', 'Uma VPC tem sub-redes privadas em três AZs, todas usando um único NAT gateway na AZ-a. O que acontece se a AZ-a falhar e como corrigir?', '[{"id": "a", "text": "As sub-redes das outras AZs perdem acesso à internet; criar um NAT gateway por AZ com rotas locais"}, {"id": "b", "text": "As instâncias passam a usar o internet gateway automaticamente"}, {"id": "c", "text": "O tráfego é redirecionado automaticamente para um NAT em outra Região"}, {"id": "d", "text": "Nada acontece, pois o NAT gateway é regional"}]'::jsonb, array['a'], 'O NAT gateway é um recurso zonal. Para alta disponibilidade, cada AZ deve ter o próprio NAT gateway, e as tabelas de rotas de cada AZ devem apontar para o NAT local.', 'medium', 'NAT gateway pertence a uma única AZ.'),
  ('saa', 'Arquiteturas Resilientes', 'A conexão Direct Connect é o único caminho entre o datacenter e a AWS. A empresa quer um caminho de contingência com o menor custo. Qual opção usar?', '[{"id": "a", "text": "Um internet gateway adicional"}, {"id": "b", "text": "Um segundo Direct Connect no mesmo local"}, {"id": "c", "text": "Uma Site-to-Site VPN como backup do Direct Connect"}, {"id": "d", "text": "Um VPC peering com outra Região"}]'::jsonb, array['c'], 'Uma VPN pela internet é a contingência de menor custo para o Direct Connect. Para máxima resiliência, a AWS recomenda conexões em locais diferentes, com custo maior.', 'medium', 'Contingência barata pela internet.'),
  ('saa', 'Arquiteturas Resilientes', 'Um serviço ECS no Fargate roda 6 tarefas e deve continuar disponível mesmo se uma Zona de Disponibilidade falhar. Como configurar?', '[{"id": "a", "text": "Usar uma única tarefa com 6 vezes mais memória"}, {"id": "b", "text": "Executar as tarefas em um cluster placement group"}, {"id": "c", "text": "Configurar o serviço com sub-redes em várias AZs, para que as tarefas sejam distribuídas entre elas, atrás de um ALB"}, {"id": "d", "text": "Colocar todas as tarefas em uma única sub-rede com mais CPU"}]'::jsonb, array['c'], 'Com sub-redes em várias AZs, o ECS distribui as tarefas entre elas, e o ALB envia tráfego só para as tarefas saudáveis.', 'medium', 'Distribuir entre AZs elimina o ponto único de falha.'),
  ('saa', 'Arquiteturas Resilientes', 'Uma função Lambda grava em um banco RDS e, em picos, milhares de execuções simultâneas derrubam o banco. Qual configuração do Lambda limita o impacto?', '[{"id": "a", "text": "Ativar a concorrência provisionada em 1.000"}, {"id": "b", "text": "Definir concorrência reservada (reserved concurrency) na função para limitar as execuções simultâneas"}, {"id": "c", "text": "Aumentar o timeout da função"}, {"id": "d", "text": "Aumentar a memória da função"}]'::jsonb, array['b'], 'A concorrência reservada garante e também limita o número máximo de execuções simultâneas, protegendo recursos downstream. A concorrência provisionada não impõe limite, apenas reduz cold starts.', 'medium', 'Limitar quantas execuções rodam ao mesmo tempo.'),
  ('saa', 'Arquiteturas Resilientes', 'Um registro alias do Route 53 aponta para um ALB em cada Região, com política de failover. Como fazer o Route 53 considerar a saúde dos alvos do ALB sem criar health checks separados?', '[{"id": "a", "text": "Reduzir o TTL do registro para 0"}, {"id": "b", "text": "Ativar ''Evaluate target health'' nos registros alias"}, {"id": "c", "text": "Criar um alarme de CPU nas instâncias"}, {"id": "d", "text": "Usar uma política de roteamento simples"}]'::jsonb, array['b'], 'Em registros alias, ''Evaluate target health'' faz o Route 53 herdar a saúde do recurso de destino. Se o ALB não tiver alvos saudáveis, o failover acontece.', 'medium', 'Registros alias podem herdar a saúde do destino.'),
  ('saa', 'Arquiteturas Resilientes', 'Quais ações tornam a camada web de uma aplicação altamente disponível? (Escolha DUAS)', '[{"id": "a", "text": "Trocar as instâncias por um único tipo maior"}, {"id": "b", "text": "Colocar um Application Load Balancer na frente das instâncias"}, {"id": "c", "text": "Colocar todas as instâncias em um cluster placement group"}, {"id": "d", "text": "Usar um único NAT gateway para todas as AZs"}, {"id": "e", "text": "Distribuir as instâncias em um Auto Scaling group em várias Zonas de Disponibilidade"}]'::jsonb, array['b', 'e'], 'Várias AZs com Auto Scaling eliminam a dependência de um único datacenter, e o ALB distribui o tráfego somente para as instâncias saudáveis.', 'medium', 'Elimine as opções que concentram tudo em um lugar.'),
  ('saa', 'Arquiteturas Resilientes', 'Um sistema recebe picos imprevisíveis de pedidos que o backend não consegue absorver na hora. Quais mudanças tornam a arquitetura resiliente a esses picos? (Escolha DUAS)', '[{"id": "a", "text": "Remover o Auto Scaling para evitar instabilidade"}, {"id": "b", "text": "Aumentar o timeout do front-end para 15 minutos"}, {"id": "c", "text": "Colocar uma fila SQS entre o front-end e o backend"}, {"id": "d", "text": "Processar os pedidos de forma síncrona com mais retentativas no navegador"}, {"id": "e", "text": "Escalar os workers do backend com base no tamanho da fila"}]'::jsonb, array['c', 'e'], 'A fila absorve os picos e guarda o trabalho com durabilidade, e escalar os workers pela profundidade da fila ajusta a capacidade ao volume real.', 'medium', 'Absorver o pico e ajustar a capacidade ao trabalho pendente.'),
  ('saa', 'Arquiteturas Resilientes', 'Um banco Aurora PostgreSQL precisa de RPO de segundos na perda de uma Região, mas a empresa quer evitar custo de instâncias grandes ociosas na Região secundária. Qual configuração atende?', '[{"id": "a", "text": "Exportação diária do banco para o S3 com replicação entre Regiões"}, {"id": "b", "text": "Snapshots do Aurora copiados a cada hora para outra Região"}, {"id": "c", "text": "Aurora Multi-AZ em uma única Região"}, {"id": "d", "text": "Aurora Global Database com um cluster secundário pequeno ou com instâncias Aurora Serverless v2"}]'::jsonb, array['d'], 'O Aurora Global Database replica com atraso tipicamente inferior a um segundo. O cluster secundário pode ser pequeno ou usar Serverless v2 e crescer só durante o failover.', 'hard', 'Replicação rápida entre Regiões sem secundário superdimensionado.'),
  ('saa', 'Arquiteturas Resilientes', 'Qual afirmação sobre Zonas de Disponibilidade é importante ao projetar alta disponibilidade?', '[{"id": "a", "text": "Uma AZ é sempre um único datacenter"}, {"id": "b", "text": "Cada AZ fica em um continente diferente"}, {"id": "c", "text": "Instâncias em AZs diferentes não conseguem se comunicar"}, {"id": "d", "text": "Elas são fisicamente separadas e isoladas de falhas, conectadas por rede de baixa latência dentro da Região"}]'::jsonb, array['d'], 'Cada AZ tem energia, refrigeração e rede independentes, mas todas se conectam por links de baixa latência, o que permite replicação síncrona entre elas.', 'easy', 'Isoladas para falhas, próximas para replicação.'),
  ('saa', 'Arquiteturas Resilientes', 'Durante um deploy, a equipe quer substituir gradualmente as instâncias de um Auto Scaling group pela nova AMI, mantendo pelo menos 90% da capacidade saudável. Qual recurso usar?', '[{"id": "a", "text": "Instance refresh do Auto Scaling com porcentagem mínima de instâncias saudáveis"}, {"id": "b", "text": "Alterar a AMI e reiniciar todas as instâncias ao mesmo tempo"}, {"id": "c", "text": "Apagar o grupo e criar outro com a nova AMI"}, {"id": "d", "text": "Criar snapshots das instâncias antigas"}]'::jsonb, array['a'], 'O instance refresh troca as instâncias em lotes, respeitando a porcentagem mínima saudável e o tempo de aquecimento, e pode reverter se algo falhar.', 'medium', 'Troca gradual dentro do próprio ASG.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação grava dados no banco e quer que o cache ElastiCache esteja sempre atualizado, evitando leituras de dados velhos, mesmo que isso aumente o custo de escrita. Qual estratégia de cache usar?', '[{"id": "a", "text": "Write-through: gravar no cache sempre que gravar no banco"}, {"id": "b", "text": "Gravar apenas no cache e nunca no banco"}, {"id": "c", "text": "Sem TTL e sem atualização do cache"}, {"id": "d", "text": "Lazy loading: preencher o cache só quando houver cache miss"}]'::jsonb, array['a'], 'No write-through, cada escrita atualiza banco e cache, então o cache nunca fica desatualizado. O lazy loading só carrega dados no cache quando há um miss e pode servir dados velhos até o TTL expirar.', 'hard', 'Dados sempre atualizados no cache.'),
  ('saa', 'Arquiteturas de Alta Performance', 'O tráfego de leitura de um cluster Aurora varia muito ao longo do dia. Como ajustar automaticamente a capacidade de leitura?', '[{"id": "a", "text": "Ativar o Auto Scaling de réplicas do Aurora, que adiciona e remove réplicas conforme métricas"}, {"id": "b", "text": "Ativar backups contínuos"}, {"id": "c", "text": "Criar réplicas de leitura em outra Região"}, {"id": "d", "text": "Aumentar a instância de escrita manualmente nos horários de pico"}]'::jsonb, array['a'], 'O Aurora Auto Scaling ajusta o número de réplicas com base em métricas como CPU ou conexões, e o reader endpoint distribui as conexões entre elas.', 'medium', 'A capacidade de leitura vem das réplicas.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma tabela DynamoDB nova recebe tráfego imprevisível, com picos repentinos de 0 a milhares de requisições por segundo. Qual modo de capacidade é mais adequado?', '[{"id": "a", "text": "Provisionado com capacidade fixa"}, {"id": "b", "text": "Provisionado com capacidade reservada de 3 anos"}, {"id": "c", "text": "On-demand (sob demanda)"}, {"id": "d", "text": "Provisionado com Auto Scaling agendado"}]'::jsonb, array['c'], 'No modo on-demand, o DynamoDB acomoda o tráfego instantaneamente e cobra por requisição, sem planejamento de capacidade, ideal para cargas novas ou imprevisíveis.', 'medium', 'Imprevisível combina com pagar por requisição.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação grava dezenas de milhares de objetos por segundo em um bucket S3, todos sob o mesmo prefixo, e passou a receber erros 503 Slow Down. Qual é a melhor correção?', '[{"id": "a", "text": "Ativar o versionamento do bucket"}, {"id": "b", "text": "Ativar o S3 Transfer Acceleration"}, {"id": "c", "text": "Distribuir os objetos entre vários prefixos, pois o limite de requisições é por prefixo"}, {"id": "d", "text": "Trocar para a classe S3 Standard-IA"}]'::jsonb, array['c'], 'O S3 suporta pelo menos 3.500 PUT e 5.500 GET por segundo por prefixo particionado. Espalhar os objetos em vários prefixos multiplica o throughput disponível.', 'hard', 'O limite de requisições é aplicado por prefixo.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação precisa baixar partes específicas de arquivos de vários GB no S3, em paralelo, para acelerar o processamento. Qual recurso usar?', '[{"id": "a", "text": "Upload multipart"}, {"id": "b", "text": "S3 Transfer Acceleration"}, {"id": "c", "text": "Requisições GET com intervalo de bytes (byte-range fetches)"}, {"id": "d", "text": "Replicação entre Regiões"}]'::jsonb, array['c'], 'Byte-range fetches permitem baixar faixas específicas de um objeto, inclusive em paralelo, melhorando o throughput e a resiliência a falhas parciais.', 'hard', 'Ler apenas pedaços do objeto, ao mesmo tempo.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um data warehouse Redshift precisa consultar dados históricos que estão em arquivos Parquet no S3, sem carregá-los no cluster. Qual recurso usar?', '[{"id": "a", "text": "Amazon DynamoDB Streams"}, {"id": "b", "text": "Amazon Redshift Spectrum"}, {"id": "c", "text": "Amazon ElastiCache"}, {"id": "d", "text": "AWS DataSync"}]'::jsonb, array['b'], 'O Redshift Spectrum consulta dados diretamente no S3 usando o mecanismo do Redshift, permitindo juntar tabelas do cluster com dados do data lake.', 'medium', 'Consultar o data lake a partir do data warehouse.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma empresa quer entregar fluxos de logs no S3 em formato Parquet, a cada poucos minutos, sem escrever ou gerenciar código de consumidor. Qual serviço usar?', '[{"id": "a", "text": "Amazon Kinesis Data Streams com consumidores em EC2"}, {"id": "b", "text": "AWS Glue DataBrew"}, {"id": "c", "text": "Amazon SQS com Lambda"}, {"id": "d", "text": "Amazon Data Firehose (antigo Kinesis Data Firehose)"}]'::jsonb, array['d'], 'O Data Firehose recebe dados de streaming, pode convertê-los para Parquet e entrega em lotes no S3, Redshift, OpenSearch e outros destinos, de forma totalmente gerenciada.', 'medium', 'Entrega de streaming sem código de consumidor.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um stream do Kinesis Data Streams em modo provisionado recebe 8 MB/s de escrita e os produtores recebem erros de throughput excedido. O stream tem 4 shards. O que fazer?', '[{"id": "a", "text": "Reduzir o número de consumidores"}, {"id": "b", "text": "Aumentar o número de shards, já que cada shard aceita até 1 MB/s de escrita"}, {"id": "c", "text": "Aumentar o período de retenção do stream"}, {"id": "d", "text": "Ativar o enhanced fan-out nos consumidores"}]'::jsonb, array['b'], 'Em modo provisionado, cada shard aceita até 1 MB/s ou 1.000 registros por segundo de escrita. Com 8 MB/s são necessários pelo menos 8 shards, ou o modo on-demand. O enhanced fan-out melhora a leitura, não a escrita.', 'hard', 'Calcule a capacidade de escrita por shard.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um banco de dados transacional em EC2 precisa de 100.000 IOPS sustentados com latência abaixo de 1 ms em um único volume. Qual volume EBS escolher?', '[{"id": "a", "text": "sc1 (HDD frio)"}, {"id": "b", "text": "st1 (HDD otimizado para throughput)"}, {"id": "c", "text": "gp2"}, {"id": "d", "text": "io2 Block Express (Provisioned IOPS SSD)"}]'::jsonb, array['d'], 'Volumes io2 Block Express oferecem IOPS provisionados muito altos, latência inferior a milissegundo e alta durabilidade, para bancos de missão crítica.', 'medium', 'Desempenho máximo e consistente exige IOPS provisionados.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um volume gp2 de 100 GB oferece só 300 IOPS de base, e a aplicação precisa de 6.000 IOPS sem aumentar o tamanho do disco. Qual é a solução mais econômica?', '[{"id": "a", "text": "Migrar para io2 com 64.000 IOPS"}, {"id": "b", "text": "Migrar para st1"}, {"id": "c", "text": "Migrar para gp3 e provisionar os IOPS desejados, independentemente do tamanho"}, {"id": "d", "text": "Aumentar o volume gp2 para 2 TB"}]'::jsonb, array['c'], 'No gp3, IOPS e throughput são configurados separadamente do tamanho, com 3.000 IOPS de base incluídos e custo por GB menor que o gp2.', 'medium', 'No gp2, IOPS crescem com o tamanho; no gp3, não.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um sistema de arquivos EFS compartilhado tem picos de throughput imprevisíveis e a equipe não quer planejar capacidade de throughput. Qual modo usar?', '[{"id": "a", "text": "Modo de throughput Elastic"}, {"id": "b", "text": "Modo de throughput Provisioned com valor fixo"}, {"id": "c", "text": "Classe de armazenamento EFS Archive"}, {"id": "d", "text": "Montar o EFS em uma única AZ"}]'::jsonb, array['a'], 'O throughput Elastic escala automaticamente conforme a carga e cobra pelo que é usado, ideal para padrões imprevisíveis.', 'medium', 'Throughput que acompanha a demanda.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um modelo de treinamento lê milhões de arquivos de um bucket S3 várias vezes e o acesso direto ao S3 virou gargalo. Qual solução oferece um sistema de arquivos de alta performance ligado ao bucket?', '[{"id": "a", "text": "Amazon FSx for Lustre vinculado ao bucket S3"}, {"id": "b", "text": "Amazon EFS com classe Infrequent Access"}, {"id": "c", "text": "AWS Storage Gateway File Gateway"}, {"id": "d", "text": "Amazon S3 Glacier Instant Retrieval"}]'::jsonb, array['a'], 'O FSx for Lustre pode ser vinculado a um bucket S3, apresentando os objetos como arquivos com throughput de centenas de GB/s e baixa latência para HPC e ML.', 'medium', 'Sistema de arquivos paralelo sobre o data lake.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação HPC usa MPI e precisa de comunicação entre nós com latência mais baixa do que a rede TCP tradicional oferece. Qual recurso de rede usar nas instâncias?', '[{"id": "a", "text": "Elastic Fabric Adapter (EFA)"}, {"id": "b", "text": "Um NAT gateway dedicado"}, {"id": "c", "text": "Elastic IP"}, {"id": "d", "text": "Elastic Network Interface adicional"}]'::jsonb, array['a'], 'O EFA é uma interface de rede com bypass do sistema operacional, feita para HPC e ML distribuído com MPI e NCCL, com latência baixa e consistente.', 'hard', 'Bypass do sistema operacional na rede.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um jogo online usa UDP e tem jogadores no mundo todo. A empresa quer reduzir a latência e o jitter fazendo o tráfego entrar na rede da AWS o mais perto possível do jogador. Qual serviço usar?', '[{"id": "a", "text": "Route 53 com política simples"}, {"id": "b", "text": "Amazon S3 Transfer Acceleration"}, {"id": "c", "text": "AWS Global Accelerator"}, {"id": "d", "text": "Amazon CloudFront com cache"}]'::jsonb, array['c'], 'O Global Accelerator usa IPs anycast e leva o tráfego TCP e UDP pela rede global da AWS desde o ponto de presença mais próximo, reduzindo latência e jitter.', 'medium', 'Tráfego UDP sem cache.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação roda em us-east-1 e eu-west-1. Os usuários devem ser direcionados à Região que oferece a menor latência para eles. Qual política do Route 53 usar?', '[{"id": "a", "text": "Roteamento simples"}, {"id": "b", "text": "Roteamento ponderado 50/50"}, {"id": "c", "text": "Roteamento baseado em latência"}, {"id": "d", "text": "Roteamento por geolocalização"}]'::jsonb, array['c'], 'O roteamento por latência responde com o registro da Região que oferece menor latência para o usuário, com base em medições da AWS. A geolocalização decide pela localização, não pelo desempenho.', 'medium', 'O critério é desempenho, não país.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma função Lambda de processamento de imagens está lenta e limitada por CPU. Como aumentar a capacidade de CPU disponível para ela?', '[{"id": "a", "text": "Colocar a função dentro de uma VPC"}, {"id": "b", "text": "Aumentar a memória configurada, pois a CPU é alocada proporcionalmente"}, {"id": "c", "text": "Ativar a concorrência reservada"}, {"id": "d", "text": "Aumentar o timeout da função"}]'::jsonb, array['b'], 'No Lambda, a CPU cresce proporcionalmente à memória configurada (até 10.240 MB). Mais memória significa mais vCPU e, muitas vezes, execução mais rápida.', 'medium', 'Não há configuração direta de CPU no Lambda.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um e-commerce sabe que o tráfego triplica toda segunda-feira às 9h. As instâncias levam 10 minutos para ficar prontas e o escalonamento reativo chega atrasado. Qual estratégia usar?', '[{"id": "a", "text": "Escalonamento simples com cooldown de 1 hora"}, {"id": "b", "text": "Escalonamento agendado (scheduled scaling) aumentando a capacidade antes das 9h"}, {"id": "c", "text": "Aumentar o tamanho das instâncias permanentemente"}, {"id": "d", "text": "Rastreamento de alvo com CPU em 90%"}]'::jsonb, array['b'], 'Quando o pico é conhecido, o escalonamento agendado prepara a capacidade com antecedência, evitando o atraso do escalonamento reativo.', 'medium', 'O pico tem dia e hora marcados.'),
  ('saa', 'Arquiteturas de Alta Performance', 'O tráfego de uma aplicação segue um padrão diário e semanal recorrente, mas os horários exatos variam um pouco. A empresa quer que o Auto Scaling se antecipe aos picos automaticamente. Qual recurso usar?', '[{"id": "a", "text": "Escalonamento preditivo (predictive scaling)"}, {"id": "b", "text": "Escalonamento agendado com horário fixo"}, {"id": "c", "text": "Capacidade fixa no máximo"}, {"id": "d", "text": "Escalonamento simples por alarme"}]'::jsonb, array['a'], 'O escalonamento preditivo usa machine learning sobre o histórico de métricas para prever a demanda e provisionar capacidade antes dos picos recorrentes.', 'hard', 'Previsão baseada em histórico.'),
  ('saa', 'Arquiteturas de Alta Performance', 'As instâncias de uma aplicação levam 15 minutos para inicializar, carregando grandes caches. A equipe quer reduzir drasticamente o tempo de scale-out sem pagar por instâncias rodando ociosas. Qual recurso usar?', '[{"id": "a", "text": "Aumentar a capacidade mínima do grupo"}, {"id": "b", "text": "Warm pools do Auto Scaling com instâncias pré-inicializadas e paradas"}, {"id": "c", "text": "Usar instâncias Spot"}, {"id": "d", "text": "Diminuir o período de aquecimento das métricas"}]'::jsonb, array['b'], 'Warm pools mantêm instâncias já inicializadas em estado parado, prontas para entrar em serviço rapidamente. Instâncias paradas não cobram computação, apenas armazenamento.', 'hard', 'Deixar instâncias prontas, mas paradas.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação precisa reescrever URLs e adicionar cabeçalhos de segurança em milhões de requisições por segundo, com latência mínima, na borda do CloudFront. Qual recurso é o mais indicado?', '[{"id": "a", "text": "CloudFront Functions"}, {"id": "b", "text": "Lambda@Edge com chamadas de rede"}, {"id": "c", "text": "Instâncias EC2 como proxy reverso"}, {"id": "d", "text": "Uma função Lambda regional atrás do API Gateway"}]'::jsonb, array['a'], 'CloudFront Functions executam JavaScript leve em todos os pontos de presença, com latência de sub-milissegundo, ideais para manipular cabeçalhos e URLs. O Lambda@Edge serve para lógica mais pesada.', 'hard', 'Lógica leve, escala massiva.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um site de notícias tem usuários globais, conteúdo dinâmico gerado por um ALB em us-east-1 e partes estáticas que mudam pouco. Como reduzir a latência para todos com uma única solução?', '[{"id": "a", "text": "Replicar o bucket para todas as Regiões manualmente"}, {"id": "b", "text": "Usar um Network Load Balancer"}, {"id": "c", "text": "Colocar o CloudFront na frente do ALB, com cache para o estático e conexões otimizadas para o dinâmico"}, {"id": "d", "text": "Aumentar as instâncias do ALB"}]'::jsonb, array['c'], 'O CloudFront armazena em cache o conteúdo estático e acelera o dinâmico ao reutilizar conexões persistentes com a origem pela rede da AWS.', 'medium', 'CDN também acelera conteúdo dinâmico.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Usuários da Europa leem dados de um banco Aurora em us-east-1 e sofrem com latência alta. As escritas são raras. Como reduzir a latência de leitura?', '[{"id": "a", "text": "Usar o Aurora Global Database com um cluster secundário em uma Região europeia para leituras locais"}, {"id": "b", "text": "Ativar o Multi-AZ na mesma Região"}, {"id": "c", "text": "Usar um NAT gateway na Europa"}, {"id": "d", "text": "Aumentar a instância de escrita em us-east-1"}]'::jsonb, array['a'], 'O Aurora Global Database mantém clusters secundários somente leitura em outras Regiões, com replicação de baixa latência, permitindo leituras locais.', 'medium', 'Leve os dados para perto dos leitores.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação de mensagens precisa de um banco chave-valor com latência de um dígito de milissegundo em qualquer escala e tráfego de milhões de requisições por segundo. Qual serviço é o mais adequado?', '[{"id": "a", "text": "Amazon S3"}, {"id": "b", "text": "Amazon Redshift"}, {"id": "c", "text": "Amazon DynamoDB"}, {"id": "d", "text": "Amazon RDS for PostgreSQL"}]'::jsonb, array['c'], 'O DynamoDB oferece desempenho de milissegundos de um dígito em praticamente qualquer escala, com particionamento automático.', 'medium', 'Chave-valor em escala massiva.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um processamento de vídeo em lote precisa de alto throughput sequencial de disco com o menor custo por GB, sem exigência de IOPS altos. Qual volume EBS escolher?', '[{"id": "a", "text": "st1 (HDD otimizado para throughput)"}, {"id": "b", "text": "Instance store NVMe"}, {"id": "c", "text": "gp3 com IOPS máximos"}, {"id": "d", "text": "io2 Block Express"}]'::jsonb, array['a'], 'Volumes st1 são HDDs de baixo custo otimizados para cargas sequenciais com alto throughput, como big data, logs e processamento de vídeo.', 'medium', 'Leitura sequencial grande, não acessos aleatórios.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma API recebe tráfego em rajadas e o backend em EC2 tem capacidade limitada. Como proteger o backend sem perder o controle por cliente?', '[{"id": "a", "text": "Aumentar o timeout do backend"}, {"id": "b", "text": "Configurar throttling e planos de uso no API Gateway"}, {"id": "c", "text": "Usar um NAT gateway"}, {"id": "d", "text": "Desativar o Auto Scaling"}]'::jsonb, array['b'], 'O API Gateway aplica limites de taxa e de rajada por estágio, método ou cliente (com planos de uso e chaves de API), protegendo o backend de sobrecarga.', 'medium', 'Limitar a taxa antes de chegar ao backend.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação precisa de consultas analíticas interativas e ad hoc em logs no S3, sem infraestrutura e com resultados em segundos. Qual serviço usar?', '[{"id": "a", "text": "Amazon RDS"}, {"id": "b", "text": "AWS Batch"}, {"id": "c", "text": "Amazon Neptune"}, {"id": "d", "text": "Amazon Athena"}]'::jsonb, array['d'], 'O Athena executa SQL diretamente sobre dados no S3, sem servidores, cobrando pelos dados lidos, ideal para análises ad hoc.', 'medium', 'SQL serverless sobre o S3.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação de streaming tem 5 consumidores diferentes lendo o mesmo Kinesis Data Stream, e cada um sofre com throughput de leitura insuficiente. Qual recurso resolve?', '[{"id": "a", "text": "Trocar para SQS FIFO"}, {"id": "b", "text": "Reduzir o número de produtores"}, {"id": "c", "text": "Enhanced fan-out, dando a cada consumidor 2 MB/s por shard dedicados"}, {"id": "d", "text": "Aumentar o período de retenção"}]'::jsonb, array['c'], 'Sem enhanced fan-out, os consumidores dividem 2 MB/s de leitura por shard. Com ele, cada consumidor registrado recebe a própria cota de 2 MB/s por shard via push.', 'hard', 'Os consumidores estão disputando a mesma cota de leitura.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Um site guarda sessões de usuário na memória de cada instância e, com o Auto Scaling, usuários perdem a sessão. Qual solução de alta performance resolve?', '[{"id": "a", "text": "Guardar as sessões no S3 Glacier"}, {"id": "b", "text": "Gravar as sessões no disco EBS de cada instância"}, {"id": "c", "text": "Armazenar as sessões em um cache distribuído como o ElastiCache"}, {"id": "d", "text": "Ativar sticky sessions e desligar o Auto Scaling"}]'::jsonb, array['c'], 'Externalizar o estado em um cache em memória compartilhado torna as instâncias stateless e mantém leituras de sessão com latência de submilissegundo.', 'medium', 'Torne as instâncias sem estado.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Quais mudanças melhoram o desempenho de leitura de um banco RDS sobrecarregado por consultas repetidas? (Escolha DUAS)', '[{"id": "a", "text": "Adicionar réplicas de leitura e direcionar as consultas de leitura para elas"}, {"id": "b", "text": "Ativar a criptografia com KMS"}, {"id": "c", "text": "Colocar um cache ElastiCache na frente das consultas mais frequentes"}, {"id": "d", "text": "Diminuir o tamanho do armazenamento alocado"}, {"id": "e", "text": "Ativar backups automáticos com retenção maior"}]'::jsonb, array['a', 'c'], 'Réplicas de leitura escalam leituras horizontalmente e um cache em memória evita consultas repetidas ao banco. Backup e criptografia não aumentam a capacidade de leitura.', 'medium', 'Pense em dividir a carga e em evitar idas ao banco.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação web dinâmica em us-east-1 tem usuários no mundo todo e um banco Aurora com muitas leituras. Quais mudanças reduzem a latência global? (Escolha DUAS)', '[{"id": "a", "text": "Aumentar a instância de escrita do Aurora"}, {"id": "b", "text": "Mover os dados para o S3 Glacier"}, {"id": "c", "text": "Usar o Aurora Global Database com leituras em Regiões próximas aos usuários"}, {"id": "d", "text": "Usar o CloudFront na frente da aplicação"}, {"id": "e", "text": "Adicionar um NAT gateway em cada AZ"}]'::jsonb, array['c', 'd'], 'O CloudFront aproxima a entrega do usuário e acelera a conexão com a origem, enquanto clusters secundários do Aurora permitem leituras locais em outras Regiões.', 'hard', 'Aproximar a entrega e os dados dos usuários.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Milhares de dispositivos enviam leituras de sensores e a aplicação precisa processá-las em tempo real com várias funções Lambda, mantendo a ordem por dispositivo. Qual fonte de eventos usar?', '[{"id": "a", "text": "Amazon SNS Standard"}, {"id": "b", "text": "Amazon SQS Standard"}, {"id": "c", "text": "Amazon S3 com notificações de eventos"}, {"id": "d", "text": "Kinesis Data Streams com o ID do dispositivo como chave de partição"}]'::jsonb, array['d'], 'No Kinesis, registros com a mesma chave de partição vão para o mesmo shard e mantêm a ordem, e o Lambda processa os lotes de cada shard em sequência.', 'medium', 'A chave de partição preserva a ordem.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Exames médicos são consultados cerca de uma vez por trimestre, mas, quando solicitados, precisam abrir em milissegundos. Qual classe S3 tem o menor custo para esse padrão?', '[{"id": "a", "text": "S3 Glacier Flexible Retrieval"}, {"id": "b", "text": "S3 Glacier Deep Archive"}, {"id": "c", "text": "S3 Standard"}, {"id": "d", "text": "S3 Glacier Instant Retrieval"}]'::jsonb, array['d'], 'O Glacier Instant Retrieval é feito para dados raramente acessados que exigem recuperação em milissegundos, com armazenamento mais barato que o Standard-IA.', 'medium', 'Acesso raro, mas instantâneo.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma frota EC2 de microsserviços em x86 roda workloads em Java e Python sem dependências de arquitetura. Qual mudança costuma gerar a maior melhoria de preço por desempenho?', '[{"id": "a", "text": "Trocar para Dedicated Hosts"}, {"id": "b", "text": "Usar volumes io2 em todas as instâncias"}, {"id": "c", "text": "Migrar para instâncias baseadas em AWS Graviton (ARM)"}, {"id": "d", "text": "Migrar para instâncias da geração anterior"}]'::jsonb, array['c'], 'Instâncias Graviton oferecem até 40% melhor preço por desempenho que instâncias x86 comparáveis, e linguagens interpretadas ou JVM normalmente rodam sem alterações.', 'medium', 'Arquitetura de processador própria da AWS.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Um processamento tolerante a interrupções usa instâncias Spot e sofre interrupções frequentes porque depende de um único tipo de instância. Como reduzir as interrupções mantendo o custo baixo?', '[{"id": "a", "text": "Diversificar os tipos de instância e usar a estratégia de alocação price-capacity-optimized"}, {"id": "b", "text": "Usar um único tipo de instância maior"}, {"id": "c", "text": "Trocar para instâncias sob demanda"}, {"id": "d", "text": "Definir o preço máximo do Spot como o menor possível"}]'::jsonb, array['a'], 'Diversificar tipos e AZs aumenta os pools disponíveis, e a estratégia price-capacity-optimized escolhe pools com capacidade abundante e preço baixo, reduzindo interrupções.', 'hard', 'Mais pools de capacidade, menos interrupções.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Um script de relatórios roda 3 vezes por dia por 2 minutos em uma instância EC2 ligada 24/7. Qual mudança reduz mais o custo?', '[{"id": "a", "text": "Trocar a instância por uma maior"}, {"id": "b", "text": "Migrar o script para AWS Lambda acionado por agendamento do EventBridge"}, {"id": "c", "text": "Comprar uma Instância Reservada para a instância atual"}, {"id": "d", "text": "Mover a instância para outra Região"}]'::jsonb, array['b'], 'Com Lambda, paga-se só pelos poucos minutos de execução, em vez de 24 horas de uma instância ociosa. O EventBridge Scheduler aciona a função nos horários desejados.', 'medium', 'Pague só pelos minutos de execução.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma tabela DynamoDB tem tráfego estável e previsível 24/7, e está em modo on-demand. Como reduzir o custo?', '[{"id": "a", "text": "Ativar o DynamoDB Accelerator (DAX)"}, {"id": "b", "text": "Mudar para o modo provisionado com Auto Scaling e considerar capacidade reservada"}, {"id": "c", "text": "Manter on-demand e aumentar o TTL"}, {"id": "d", "text": "Criar mais índices secundários globais"}]'::jsonb, array['b'], 'O modo on-demand é ideal para tráfego imprevisível. Para uso estável, o modo provisionado com Auto Scaling, e eventualmente capacidade reservada, costuma sair bem mais barato.', 'hard', 'Previsível combina com capacidade provisionada.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma empresa tem centenas de volumes gp2. Qual mudança reduz o custo de armazenamento mantendo ou melhorando o desempenho de base?', '[{"id": "a", "text": "Criar snapshots diários de todos os volumes"}, {"id": "b", "text": "Migrar todos os volumes para io2"}, {"id": "c", "text": "Migrar os volumes para gp3, que tem custo por GB menor e 3.000 IOPS de base"}, {"id": "d", "text": "Migrar para instance store"}]'::jsonb, array['c'], 'O gp3 custa cerca de 20% menos por GB que o gp2 e oferece desempenho de base independente do tamanho. A migração é feita sem parar a instância (Elastic Volumes).', 'medium', 'A geração mais nova de SSD de uso geral.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'A fatura mostra custo alto de volumes EBS e snapshots antigos. A análise revela volumes desanexados há meses e snapshots que precisam ser retidos por anos, mas quase nunca restaurados. Qual ação reduz o custo?', '[{"id": "a", "text": "Copiar todos os snapshots para outra Região"}, {"id": "b", "text": "Apagar os volumes desanexados desnecessários e mover snapshots raramente usados para o EBS Snapshots Archive"}, {"id": "c", "text": "Converter os volumes para io2"}, {"id": "d", "text": "Anexar os volumes a novas instâncias"}]'::jsonb, array['b'], 'Volumes desanexados continuam cobrando. O EBS Snapshots Archive reduz em até 75% o custo de snapshots retidos por longo prazo e raramente restaurados.', 'medium', 'Recurso parado ainda cobra.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma aplicação transfere terabytes por mês entre instâncias EC2 e um banco em Zonas de Disponibilidade diferentes, e esse tráfego virou um custo relevante. O que explica esse custo?', '[{"id": "a", "text": "O custo vem do internet gateway"}, {"id": "b", "text": "Transferência de dados entre AZs é cobrada em cada direção"}, {"id": "c", "text": "Tráfego dentro da mesma Região é sempre gratuito"}, {"id": "d", "text": "O custo vem do tamanho das instâncias"}]'::jsonb, array['b'], 'Dentro da mesma Região, a transferência entre AZs é cobrada por GB em cada direção. Arquiteturas com tráfego intenso entre AZs devem considerar esse custo ao equilibrar resiliência e economia.', 'hard', 'Atravessar AZs não é de graça.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma empresa quer visibilidade de uso e custo do S3 em todas as contas da organização, com recomendações como buckets sem regras de ciclo de vida. Qual recurso usar?', '[{"id": "a", "text": "S3 Inventory de um único bucket"}, {"id": "b", "text": "AWS Trusted Advisor com verificações básicas"}, {"id": "c", "text": "AWS Config"}, {"id": "d", "text": "Amazon S3 Storage Lens"}]'::jsonb, array['d'], 'O S3 Storage Lens agrega métricas de uso e atividade de armazenamento em toda a organização e aponta oportunidades de otimização de custo e de proteção de dados.', 'medium', 'Uma lente sobre todo o armazenamento S3.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Um arquivo de 500 TB raramente é consultado e, quando necessário, a equipe aceita esperar de 5 a 12 horas pela recuperação, desde que não pague taxa de recuperação. Qual classe e opção usar?', '[{"id": "a", "text": "S3 Glacier Flexible Retrieval com recuperação expressa"}, {"id": "b", "text": "S3 Glacier Instant Retrieval"}, {"id": "c", "text": "S3 Glacier Flexible Retrieval com recuperação em massa (bulk)"}, {"id": "d", "text": "S3 Standard-IA"}]'::jsonb, array['c'], 'No Glacier Flexible Retrieval, a recuperação em massa leva de 5 a 12 horas e não tem cobrança por GB recuperado, a opção mais barata para grandes restaurações sem urgência.', 'medium', 'A pressa custa caro.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Um banco RDS de produção vai rodar 24/7 pelos próximos 3 anos sem mudanças de tipo. Qual opção reduz mais o custo do banco?', '[{"id": "a", "text": "Instâncias Spot"}, {"id": "b", "text": "Manter sob demanda"}, {"id": "c", "text": "Instâncias Reservadas do RDS de 3 anos"}, {"id": "d", "text": "Mudar para uma instância maior e parar à noite"}]'::jsonb, array['c'], 'O RDS oferece instâncias reservadas com desconto significativo em relação ao sob demanda para uso contínuo. O RDS não usa instâncias Spot.', 'easy', 'Bancos também têm modelo de reserva.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'O financeiro quer saber quanto cada equipe gasta na AWS, mas todos os recursos estão na mesma conta. Qual é o primeiro passo?', '[{"id": "a", "text": "Aplicar tags de alocação de custo (como Equipe) e ativá-las no Billing para filtrar no Cost Explorer"}, {"id": "b", "text": "Comprar Savings Plans por equipe"}, {"id": "c", "text": "Mover cada equipe para outra Região"}, {"id": "d", "text": "Criar um usuário IAM por equipe"}]'::jsonb, array['a'], 'Tags de alocação de custo ativadas aparecem nos relatórios de cobrança e no Cost Explorer, permitindo agrupar gastos por equipe, projeto ou ambiente.', 'medium', 'Rotular os recursos para separar os gastos.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'A empresa quer que, ao atingir 100% do orçamento mensal de uma conta de testes, as instâncias EC2 dessa conta sejam paradas automaticamente. Qual recurso usar?', '[{"id": "a", "text": "Cost Explorer com previsão"}, {"id": "b", "text": "AWS Cost Anomaly Detection"}, {"id": "c", "text": "Trusted Advisor"}, {"id": "d", "text": "Ações do AWS Budgets (budget actions)"}]'::jsonb, array['d'], 'As ações do AWS Budgets podem aplicar políticas IAM ou SCPs ou parar instâncias EC2 e RDS automaticamente quando um limite de orçamento é atingido.', 'hard', 'Orçamentos podem agir, não só alertar.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Tarefas ECS de processamento em lote podem ser interrompidas e reiniciadas sem problema. Como reduzir o custo de computação delas no Fargate?', '[{"id": "a", "text": "Usar o Fargate Spot nos provedores de capacidade"}, {"id": "b", "text": "Aumentar a CPU de cada tarefa"}, {"id": "c", "text": "Usar Dedicated Hosts"}, {"id": "d", "text": "Comprar Instâncias Reservadas de EC2"}]'::jsonb, array['a'], 'O Fargate Spot executa tarefas com grande desconto sobre o preço do Fargate, usando capacidade ociosa, com aviso de 2 minutos antes da interrupção.', 'medium', 'Capacidade ociosa também existe no Fargate.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Consumidores de uma fila SQS fazem milhões de chamadas ReceiveMessage que voltam vazias, gerando custo. Como reduzir essas chamadas?', '[{"id": "a", "text": "Reduzir o visibility timeout"}, {"id": "b", "text": "Ativar long polling com tempo de espera de até 20 segundos"}, {"id": "c", "text": "Aumentar o período de retenção"}, {"id": "d", "text": "Trocar para SQS FIFO"}]'::jsonb, array['b'], 'Com long polling, o SQS espera mensagens chegarem antes de responder, reduzindo respostas vazias e o número de requisições cobradas.', 'medium', 'Esperar um pouco antes de responder.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'O custo do CloudWatch Logs cresce todo mês porque os grupos de logs guardam tudo para sempre, mas a equipe só consulta os últimos 30 dias. O que fazer?', '[{"id": "a", "text": "Criar mais grupos de logs"}, {"id": "b", "text": "Desativar os logs da aplicação"}, {"id": "c", "text": "Definir a retenção dos grupos de logs em 30 dias e exportar para o S3 o que precisa ser arquivado"}, {"id": "d", "text": "Aumentar a resolução das métricas"}]'::jsonb, array['c'], 'Por padrão, os logs do CloudWatch nunca expiram. Configurar retenção evita acúmulo, e o S3 com ciclo de vida é mais barato para arquivamento.', 'medium', 'Por padrão, os logs nunca expiram.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma empresa hospeda um site institucional estático em duas instâncias EC2 com ALB. Qual alternativa reduz drasticamente o custo e a manutenção?', '[{"id": "a", "text": "Usar Dedicated Hosts"}, {"id": "b", "text": "Usar instâncias EC2 maiores"}, {"id": "c", "text": "Trocar o ALB por um NLB"}, {"id": "d", "text": "Hospedar os arquivos no S3 servidos pelo CloudFront"}]'::jsonb, array['d'], 'Sites estáticos não precisam de servidores: S3 com CloudFront entrega o conteúdo com alta disponibilidade, HTTPS e custo por uso.', 'easy', 'Conteúdo estático não precisa de servidor.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma tabela DynamoDB acumula sessões expiradas que ninguém lê, aumentando o custo de armazenamento. Qual é a forma mais barata de removê-las?', '[{"id": "a", "text": "Usar o DynamoDB Streams para apagar itens"}, {"id": "b", "text": "Criar uma nova tabela a cada mês"}, {"id": "c", "text": "Ativar o TTL (Time to Live) com um atributo de expiração"}, {"id": "d", "text": "Executar um scan diário com Lambda apagando itens antigos"}]'::jsonb, array['c'], 'O TTL apaga automaticamente os itens expirados sem consumir capacidade de escrita, sem custo adicional e sem código.', 'medium', 'Exclusão automática e gratuita.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma equipe de análise roda consultas no Redshift apenas algumas horas por semana, em horários irregulares. Qual opção evita pagar por um cluster ocioso?', '[{"id": "a", "text": "Amazon Redshift Serverless, cobrado pela capacidade usada durante as consultas"}, {"id": "b", "text": "Amazon RDS for MySQL"}, {"id": "c", "text": "Um cluster provisionado maior"}, {"id": "d", "text": "Um cluster provisionado com Instâncias Reservadas de 3 anos"}]'::jsonb, array['a'], 'O Redshift Serverless provisiona e escala capacidade automaticamente e cobra apenas enquanto há carga, ideal para uso intermitente.', 'medium', 'Uso intermitente combina com serverless.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Consultas do Athena sobre logs em JSON leem terabytes a cada execução, gerando custo alto. Quais mudanças reduzem os dados lidos?', '[{"id": "a", "text": "Habilitar o versionamento do bucket"}, {"id": "b", "text": "Converter os dados para Parquet compactado e particionar por data"}, {"id": "c", "text": "Aumentar o número de workgroups"}, {"id": "d", "text": "Mover os logs para o S3 Glacier Deep Archive"}]'::jsonb, array['b'], 'O Athena cobra por dados lidos. Formatos colunares e compactados leem só as colunas necessárias, e partições permitem ignorar arquivos fora do período consultado.', 'medium', 'O Athena cobra pelo que lê.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma instituição de pesquisa compartilha um dataset de 100 TB no S3 com outras instituições e não quer pagar pela transferência de dados quando elas baixam os arquivos. Qual recurso usar?', '[{"id": "a", "text": "Replicação entre Regiões para cada instituição"}, {"id": "b", "text": "S3 Transfer Acceleration"}, {"id": "c", "text": "Bucket público com CloudFront"}, {"id": "d", "text": "S3 Requester Pays"}]'::jsonb, array['d'], 'Com Requester Pays, quem faz a requisição paga pelas requisições e pela transferência de dados, e o dono do bucket paga só pelo armazenamento.', 'hard', 'Quem pede, paga.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Um job noturno tolera interrupções e hoje usa instâncias sob demanda por 4 horas. Quais mudanças reduzem o custo sem perder trabalho em caso de interrupção? (Escolha DUAS)', '[{"id": "a", "text": "Usar volumes io2 com IOPS máximos"}, {"id": "b", "text": "Comprar uma Instância Reservada de 3 anos para 4 horas por dia"}, {"id": "c", "text": "Usar Instâncias Spot"}, {"id": "d", "text": "Salvar checkpoints periódicos no S3 para retomar o processamento"}, {"id": "e", "text": "Comprar Dedicated Hosts"}]'::jsonb, array['c', 'd'], 'Instâncias Spot oferecem grande desconto para cargas interrompíveis, e checkpoints permitem retomar do ponto em que parou em vez de recomeçar.', 'medium', 'Desconto pela interrupção e um jeito de não perder trabalho.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Quais ações reduzem o custo de funções Lambda de uso intenso? (Escolha DUAS)', '[{"id": "a", "text": "Usar a arquitetura arm64 (Graviton)"}, {"id": "b", "text": "Ativar a concorrência provisionada em todas as funções"}, {"id": "c", "text": "Ajustar a memória ao ponto ideal de custo e duração, com base em medições"}, {"id": "d", "text": "Colocar todas as funções em uma VPC"}, {"id": "e", "text": "Aumentar o timeout de todas as funções para 15 minutos"}]'::jsonb, array['a', 'c'], 'Encontrar a memória ideal reduz o custo em GB-segundo, e o arm64 oferece melhor preço por desempenho. Concorrência provisionada adiciona custo fixo e não deve ser usada indiscriminadamente.', 'medium', 'Medir para dimensionar e escolher uma arquitetura mais eficiente.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma empresa tem um Compute Savings Plan que cobre 70% do uso de EC2 estável. O restante varia muito e parte dele tolera interrupções. Qual combinação é mais econômica para a parcela variável?', '[{"id": "a", "text": "Instâncias Reservadas de 3 anos para os picos"}, {"id": "b", "text": "Ampliar o Savings Plan para cobrir 100% do pico"}, {"id": "c", "text": "Instâncias Spot para o que tolera interrupção e sob demanda para o restante"}, {"id": "d", "text": "Dedicated Hosts para a parcela variável"}]'::jsonb, array['c'], 'Compromissos devem cobrir só a base estável. Picos variáveis ficam mais baratos com Spot quando toleram interrupções e com sob demanda quando não toleram.', 'hard', 'Compromisso só para o que é constante.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Um ambiente de homologação usa um NAT gateway por AZ em três AZs, mas tem pouco tráfego e não exige alta disponibilidade. Como reduzir o custo fixo de rede?', '[{"id": "a", "text": "Adicionar um NAT gateway por sub-rede"}, {"id": "b", "text": "Trocar os NAT gateways por internet gateways nas sub-redes privadas"}, {"id": "c", "text": "Usar Elastic IPs em todas as instâncias privadas"}, {"id": "d", "text": "Usar um único NAT gateway compartilhado pelas sub-redes, aceitando menor resiliência nesse ambiente"}]'::jsonb, array['d'], 'Cada NAT gateway tem custo por hora. Em ambientes não críticos, um único NAT reduz o custo, com a perda de resiliência entre AZs como contrapartida consciente.', 'medium', 'Resiliência tem custo; nem todo ambiente precisa dela.'),
  ('saa', 'Arquiteturas com Custo Otimizado', 'Uma empresa recebe arquivos de parceiros no S3 e só precisa deles por 7 dias. Qual é a forma mais simples de não pagar armazenamento depois disso?', '[{"id": "a", "text": "Uma regra de ciclo de vida que expira os objetos após 7 dias"}, {"id": "b", "text": "Mover os arquivos para o Glacier Deep Archive no dia 1"}, {"id": "c", "text": "Uma Lambda agendada que apaga os arquivos manualmente"}, {"id": "d", "text": "Ativar o versionamento"}]'::jsonb, array['a'], 'Regras de expiração do ciclo de vida apagam objetos automaticamente após o prazo definido, sem código. O Deep Archive teria cobrança mínima de 180 dias.', 'medium', 'Expiração automática é nativa do S3.'),
  ('saa', 'Arquiteturas Resilientes', 'Um pipeline de pedidos usa uma fila SQS FIFO e precisa evitar que a mesma mensagem enviada duas vezes pelo produtor, por causa de retentativas de rede, seja processada em dobro. Qual recurso usar?', '[{"id": "a", "text": "ID de deduplicação de mensagem (ou deduplicação baseada em conteúdo) da fila FIFO"}, {"id": "b", "text": "Long polling de 20 segundos"}, {"id": "c", "text": "Dead-letter queue com maxReceiveCount igual a 1"}, {"id": "d", "text": "Aumentar o visibility timeout"}]'::jsonb, array['a'], 'Filas FIFO descartam mensagens com o mesmo ID de deduplicação recebidas dentro do intervalo de 5 minutos. A deduplicação baseada em conteúdo gera esse ID a partir de um hash do corpo.', 'medium', 'O problema é o produtor enviando a mesma mensagem duas vezes.'),
  ('saa', 'Arquiteturas Resilientes', 'Uma API regional atrás de um ALB em us-east-1 precisa de failover para us-west-2 em caso de falha regional, e os clientes não podem depender de cache DNS para trocar de Região. Qual solução atende?', '[{"id": "a", "text": "Replicação entre Regiões do S3"}, {"id": "b", "text": "AWS Global Accelerator com endpoints nas duas Regiões e verificações de saúde"}, {"id": "c", "text": "Route 53 com política simples e TTL de 1 dia"}, {"id": "d", "text": "Um único ALB com destinos nas duas Regiões"}]'::jsonb, array['b'], 'O Global Accelerator expõe IPs anycast estáticos e redireciona o tráfego para a Região saudável em segundos, sem depender da expiração do cache DNS dos clientes.', 'hard', 'Os IPs não mudam, só o destino por trás deles.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação faz upload de muitos arquivos pequenos para o S3 a partir de instâncias EC2 na mesma Região e a latência por requisição ficou alta. A equipe quer o menor tempo de resposta possível para dados acessados com frequência em uma única AZ. Qual classe usar?', '[{"id": "a", "text": "S3 Intelligent-Tiering com arquivamento"}, {"id": "b", "text": "S3 Express One Zone"}, {"id": "c", "text": "S3 Standard-IA"}, {"id": "d", "text": "S3 Glacier Instant Retrieval"}]'::jsonb, array['b'], 'O S3 Express One Zone é uma classe de alto desempenho em uma única AZ, com latência de um dígito de milissegundo, indicada para dados muito acessados próximos da computação.', 'medium', 'Desempenho máximo, em uma única AZ.'),
  ('saa', 'Arquiteturas de Alta Performance', 'Uma aplicação de leilões precisa de um placar com ordenação em tempo real e milhões de atualizações por segundo, com durabilidade Multi-AZ e latência de microssegundos para leitura. Qual serviço é o mais adequado?', '[{"id": "a", "text": "Amazon MemoryDB"}, {"id": "b", "text": "Amazon RDS for MySQL com réplicas"}, {"id": "c", "text": "Amazon S3 Standard"}, {"id": "d", "text": "Amazon Redshift"}]'::jsonb, array['a'], 'O MemoryDB é um banco em memória durável, compatível com Valkey e Redis OSS, com log transacional Multi-AZ. Estruturas como sorted sets atendem placares em tempo real.', 'hard', 'Banco em memória que também é durável.');
